  [239005] = { "Permette a chi lo usa di vedere temporaneamente le ombre demoniache nel ⟦Felwood=Vilbosco⟧.", 0xe41c07dc, "u" },
  [239006] = { "Combina tre Fel-Touched Flower in una pozione che mostra temporaneamente le ombre demoniache.\nDal fiore, un tempo bellissimo, emana debolmente un'energia perversa.", 0x52c3ed62, "u" },
  [239013] = { "Lame della Luce, non c'è che dire.", 0xba9ba9bc, "u" },
  [239016] = { "Usato comunemente dai crociati per scacciare la sfortuna. Per comodità, è utile anche in cucina.", 0x43c47677, "u" },
  [239017] = { "Una merce rigidamente regolamentata: comprarla o venderla direttamente sarebbe poco saggio. Ambita dai cuochi per preparare i banchetti.", 0x7a8d8a6c, "u" },
  [239021] = { "Ti insegna a cucinare i banchetti più ambiti di Carrie Hearthfire.", 0x86b738e2, "u" },
  [239119] = { "Benedetta sia la freccia che abbatte i nostri nemici.", 0x8dbf8aa6, "u" },
  [239149] = { "Ti insegna a creare un Crusader's Knapsack.", 0x771c656c, "u" },
  [239150] = { "Ti insegna a creare una Crimson Dawnwoven Bag.", 0x286d32f6, "u" },
  [239218] = { "Il documento è scritto in una stenografia sciatta, ma quel poco che riesci a capire suggerisce che questi progetti e appunti siano opera di un vero genio dell'artigianato.", 0x2fc55faf, "u" },
  [239222] = { "Ti insegna a creare un Pop-Up Shrub.", 0x901b460a, "u" },
  [239223] = { "Incredibilmente convincente, nel contesto di un'opera lirica o di uno spettacolo teatrale.", 0x52ee0f5c, "u" },
  [239225] = { "Puoi solo immaginare la soddisfazione di apporre la tua firma con questo strumento.", 0xdc6f9e2e, "u" },
  [239246] = { "Un elenco di oggetti scarabocchiato in fretta ogni volta che passava per la mente dell'autore.", 0x773643e5, "u" },
  [239292] = { "Contiene i pensieri e le opere raccolti di ⟦Franclorn Forgewright=Franclorn Forgiabruna⟧.", 0x1cd229fb, "u" },
  [239302] = { "Una spessa cinghia di cuoio con una pesante fibbia d'acciaio. Un vero capolavoro di cintura, pronto a essere rovinato da qualche armeggio sconsiderato.", 0xe9e2ed7f, "u" },
  [239316] = { "Usa il dispositivo in un punto di triangolazione designato per aiutare Fizzlefuse a calibrare il suo teletrasportatore.", 0x3fe0358d, "u" },
